import{_ as e,o as s,c as n,ai as t}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"ModelDesk 架构解析：把多个模型 API 收敛成本地一个 /v1 网关","description":"","frontmatter":{"title":"ModelDesk 架构解析：把多个模型 API 收敛成本地一个 /v1 网关","outline":"deep"},"headers":[],"relativePath":"ai/creation/modeldesk-architecture.md","filePath":"ai/creation/modeldesk-architecture.md"}'),i={name:"ai/creation/modeldesk-architecture.md"};function l(r,a,o,d,p,c){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="modeldesk-架构解析-把多个模型-api-收敛成本地一个-v1-网关" tabindex="-1">ModelDesk 架构解析：把多个模型 API 收敛成本地一个 /v1 网关 <a class="header-anchor" href="#modeldesk-架构解析-把多个模型-api-收敛成本地一个-v1-网关" aria-label="Permalink to “ModelDesk 架构解析：把多个模型 API 收敛成本地一个 /v1 网关”">​</a></h1><blockquote><p>本文基于 ModelDesk（<a href="https://github.com/gao-shu/modeldesk" target="_blank" rel="noreferrer">https://github.com/gao-shu/modeldesk</a>，MIT）的真实架构与本地验证过程写成。涉及「调用真实模型返回结果」的部分需用户自备 API Key，本人<strong>未</strong>用真实 Key 跑通业务数据；下文的「验证」均指构建 / 单测 / 冒烟层面的可复现证据。</p></blockquote><h2 id="一、问题背景" tabindex="-1">一、问题背景 <a class="header-anchor" href="#一、问题背景" aria-label="Permalink to “一、问题背景”">​</a></h2><p>做 AI 应用的人迟早会遇到同一个摩擦：要用多家模型（OpenAI、火山、智谱、本地 Ollama……）。厂商控制台适合测单个模型，但一旦要<strong>对比</strong>多家接口，就得在多个后台、多套 Key、多种返回格式之间来回切换，最后还得手工改调用代码接到业务里。</p><p>痛点拆开是三件事：</p><ol><li><strong>配置分散</strong>：Key 散落在各处，换机器就重来。</li><li><strong>对比困难</strong>：同一问题并行打 2～3 个模型，要自己拼并发、收结果、对齐延迟/Token。</li><li><strong>接入割裂</strong>：业务代码要为每个厂商写一套适配。</li></ol><h2 id="二、方案比较" tabindex="-1">二、方案比较 <a class="header-anchor" href="#二、方案比较" aria-label="Permalink to “二、方案比较”">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>取舍</th></tr></thead><tbody><tr><td>A. 业务里直接调各厂商 SDK</td><td>最快上手</td><td>厂商耦合重，换模型要改代码；Key 难统一管理</td></tr><tr><td>B. 自建一层适配服务</td><td>业务只打自己的服务</td><td>要自己维护服务、部署、Key 存储</td></tr><tr><td>C. 本机配测台 + 本地网关</td><td>配置/测试/对比在桌面完成，业务只打本机 <code>:3300/v1</code></td><td>不解决云端多租户，但<strong>本机开发场景</strong>最省事，零部署</td></tr></tbody></table><p>ModelDesk 选 <strong>C</strong>：定位是「开发者本机工具」，不碰登录、多租户、云同步。边界清晰，反而好做。</p><h2 id="三、关键设计" tabindex="-1">三、关键设计 <a class="header-anchor" href="#三、关键设计" aria-label="Permalink to “三、关键设计”">​</a></h2><h3 id="_3-1-同进程-界面即网关" tabindex="-1">3.1 同进程：界面即网关 <a class="header-anchor" href="#_3-1-同进程-界面即网关" aria-label="Permalink to “3.1 同进程：界面即网关”">​</a></h3><p>最省事的一点——<strong>Gateway 和 Web 界面同进程</strong>，默认都在 <code>http://127.0.0.1:3300</code>。业务代码指向 <code>:3300/v1</code>，不需要再起一个独立网关服务；想要无头 HTTP，也有独立的 <code>modeldesk-gateway</code>（<code>:3310</code>），契约相同。</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>业务 / 脚本 / Cursor / MCP</span></span>
<span class="line"><span>        ↓ 只打一个地址</span></span>
<span class="line"><span>http://127.0.0.1:3300/v1   ← OpenAI 兼容</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>ModelDesk（已配好模型与 Key）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>各厂商 API</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="_3-2-统一契约-别名" tabindex="-1">3.2 统一契约 + 别名 <a class="header-anchor" href="#_3-2-统一契约-别名" aria-label="Permalink to “3.2 统一契约 + 别名”">​</a></h3><p>业务里 <code>model</code> 字段可以填三种东西：<strong>稳定别名</strong>、台账 UUID、或唯一配置名。先把常用模型绑成别名：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3300/v1/aliases</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;llm-default&quot;:&quot;&lt;text-registry-id&gt;&quot;,&quot;image-default&quot;:&quot;&lt;image-registry-id&gt;&quot;}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>之后业务写死 <code>llm-default</code> / <code>image-default</code>，换模型只改别名、不动业务代码。上游 Key 只用 Desk 里已保存的——请求里即使带 Key 也不会被用来调厂商，避免把调用方 Key 误用出去。</p><h3 id="_3-3-本地优先的安全边界" tabindex="-1">3.3 本地优先的安全边界 <a class="header-anchor" href="#_3-3-本地优先的安全边界" aria-label="Permalink to “3.3 本地优先的安全边界”">​</a></h3><ul><li>API Key <strong>本地存储</strong>，落盘加密；</li><li>默认只监听 <code>localhost</code>，不暴露公网；</li><li>无登录、无多租户云同步。</li></ul><p>这是「本机工具」定位带来的天然安全优势：敏感 Key 不出本机。</p><h3 id="_3-4-monorepo-模块拆分" tabindex="-1">3.4 monorepo 模块拆分 <a class="header-anchor" href="#_3-4-monorepo-模块拆分" aria-label="Permalink to “3.4 monorepo 模块拆分”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apps/web         Next 界面（Playground / Compare / Models / Settings）</span></span>
<span class="line"><span>apps/desktop     Tauri 桌面壳（需 Rust）</span></span>
<span class="line"><span>apps/gateway     无头网关（可选）</span></span>
<span class="line"><span>apps/cli · mcp   命令行 / MCP 入口</span></span>
<span class="line"><span>packages/run-core       run 编排：并发、部分失败保留</span></span>
<span class="line"><span>packages/adapters       厂商 / 协议适配</span></span>
<span class="line"><span>packages/model-registry 配置名 ↔ 网关 model id、别名</span></span>
<span class="line"><span>packages/object-storage / tos-storage  产物 / 对象存储</span></span>
<span class="line"><span>packages/shared         导航、类型</span></span>
<span class="line"><span>packages/gateway-client TS 客户端（baseUrl → :3300）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>界面 → <code>run-core</code> → <code>adapters</code> + <code>model-registry</code> → 加密 Key / SQLite，这条主链路把「配置、测试、对比、选用」串起来。</p><h2 id="四、实际实现里的两个难点" tabindex="-1">四、实际实现里的两个难点 <a class="header-anchor" href="#四、实际实现里的两个难点" aria-label="Permalink to “四、实际实现里的两个难点”">​</a></h2><h3 id="_4-1-compare-的并发编排与「部分失败保留」" tabindex="-1">4.1 Compare 的并发编排与「部分失败保留」 <a class="header-anchor" href="#_4-1-compare-的并发编排与「部分失败保留」" aria-label="Permalink to “4.1 Compare 的并发编排与「部分失败保留」”">​</a></h3><p>对比页用相同输入并行跑 2～3 个同模态模型。难点不在「并发」，而在<strong>一路失败不能拖垮其他路</strong>：某模型超时或报错，其他列仍要正常展示结果与指标。这在 <code>run-core</code> 里通过「每个 job 独立 try/catch、聚合时标记 partial」实现，也是单测重点覆盖的路径。</p><h3 id="_4-2-适配器与注册表解耦" tabindex="-1">4.2 适配器与注册表解耦 <a class="header-anchor" href="#_4-2-适配器与注册表解耦" aria-label="Permalink to “4.2 适配器与注册表解耦”">​</a></h3><p>新增一个厂商，本质是加一个 <code>adapter</code> + 在 <code>model-registry</code> 登记映射，界面与网关契约不动。这让「支持更多模型」变成可增量扩展的能力，而不是改核心。</p><h2 id="五、验证结果-本地复现" tabindex="-1">五、验证结果（本地复现） <a class="header-anchor" href="#五、验证结果-本地复现" aria-label="Permalink to “五、验证结果（本地复现）”">​</a></h2><p>我在本地按官方流程跑了一遍，结论可复现：</p><table tabindex="0"><thead><tr><th>命令</th><th>结果</th></tr></thead><tbody><tr><td><code>pnpm install</code>（Node 22 + pnpm 9.15.0）</td><td>619 包，52.8s，成功</td></tr><tr><td><code>pnpm test:unit</code></td><td>4 包共 <strong>93 测全过</strong>（run-core 31 / adapters 36 / object-storage 20 / tos-storage 6），0 失败</td></tr><tr><td><code>pnpm smoke</code></td><td><strong>2/2</strong>（web.home、web.models 均 200）</td></tr><tr><td><code>pnpm build</code></td><td>生产构建成功，产出 <code>/models</code>、<code>/runs/compare</code>、<code>/v1/[...path]</code>、<code>/healthz</code></td></tr></tbody></table><blockquote><p>诚实边界：以上验证覆盖「能装、能构建、页面能渲染、核心单测通过」。<strong>真实模型的返回质量/延迟对比</strong>依赖用户自备 Key，我未做该部分验证，也不在本文声称。</p></blockquote><h2 id="六、局限与改进空间" tabindex="-1">六、局限与改进空间 <a class="header-anchor" href="#六、局限与改进空间" aria-label="Permalink to “六、局限与改进空间”">​</a></h2><ul><li><strong>不解决云端场景</strong>：本机工具定位，没有登录/多租户/云同步，团队共用需另起服务。</li><li><strong>不做 AI 裁判</strong>：Compare 只并排展示事实（结果/延迟/Token/错误），不做自动评分或排名——这是产品冻结时的明确边界。</li><li><strong>桌面端依赖 Rust/Tauri</strong>：纯 Web 可 <code>pnpm dev</code>，但要打安装包需 Rust 工具链。</li></ul><h2 id="七、小结" tabindex="-1">七、小结 <a class="header-anchor" href="#七、小结" aria-label="Permalink to “七、小结”">​</a></h2><p>把「多模型配置 + 对比 + 接入」收敛成本机一个 <code>:3300/v1</code>，核心价值不是又包了一层，而是<strong>让业务代码只依赖一个稳定契约和一个别名机制</strong>，模型供应商的变动被隔离在 Desk 之内。配合本地优先的安全设计，它对「单人多模型开发」场景是低成本、低风险的选型。</p><ul><li>项目详情页：<a href="/my-vitepress-site/apps/ai/modeldesk.html">ModelDesk · 本机多模态 AI 配测台</a></li><li>仓库：<a href="https://github.com/gao-shu/modeldesk" target="_blank" rel="noreferrer">https://github.com/gao-shu/modeldesk</a></li></ul>`,37)])])}const k=e(i,[["render",l]]);export{b as __pageData,k as default};
